def segments_from_pts(pts):
    by_u={}
    for r,c in pts:
        u=r+c; v=c-r
        by_u.setdefault(u,set()).add(v)
    segs=[]
    for u,vs in by_u.items():
        sv=sorted(vs)
        # contiguous increments of 2
        runs=[]; lo=prev=sv[0]
        for x in sv[1:]:
            if x==prev+2: prev=x
            else:runs.append((lo,prev));lo=prev=x
        runs.append((lo,prev))
        for lo,hi in runs:segs.append((u,lo,hi))
    return sorted(segs)
def rectfill(pts):
    segs=segments_from_pts(pts)
    filled=set()
    for i,(u1,l1,h1) in enumerate(segs):
        for u2,l2,h2 in segs[i+1:]:
            if u2==u1: continue
            lo=max(l1,l2);hi=min(h1,h2)
            if lo>hi:continue
            for u in range(u1,u2+1):
                # valid v has parity u; v endpoints stepping by two
                for v in range(lo,hi+1):
                    if (u-v)%2:continue
                    r=(u-v)//2;c=(u+v)//2
                    if 0<=r<16 and 0<=c<16 and (r,c) not in pts:
                        filled.add((r,c))
    return filled,segs
